/**
 * Function types for the CEF HTTP layer (generated by `cef-init`).
 *
 * - InputParserFn: referenced by `x-inputParser` in root.yaml. Runs synchronously and returns
 *   either the parsed input or a `Response` (which stops the request).
 * - HandlerFn: referenced by `x-handler`. Receives the parsed input and returns a plain object
 *   (sent as 200) or a `Response` (custom status code).
 */
import { CommonEvent } from "commoneventframework/dist/types/commonEvent";
import { APIGatewayProxyStructuredResultV2 } from "commoneventframework";

export type InputParserFn = (event: CommonEvent) => any;

export type HandlerFn = (input: any, event: CommonEvent) => Promise<APIGatewayProxyStructuredResultV2 | object>;
